def generate_directory_json():
    reader = csv.DictReader(raw_csv.strip().splitlines())
    services = []
    seen_urls = set()
    
    index = 1
    for row in reader:
        url = row['url'].strip()
        if not url or url in seen_urls:
            continue
        seen_urls.add(url)
        
        name = row['name'].strip()
        if not name:
            # Fallback name from category or URL domain
            domain = url.replace("https://", "").replace("http://", "").split("/")[0].replace("www.", "")
            name = domain.capitalize()
            
        desc = row['description'].strip()
        history = row['history'].strip()
        interest = row['interest'].strip()
        raw_cat = row['category'].strip()
        
        # Split categories
        cats = [c.strip() for c in re.split(r'[;,]', raw_cat) if c.strip()]
        if not cats:
            cats = ["Service Public"]
            
        # Detect if it's an interactive e-service
        is_eservice = any(
            x in (name + " " + desc + " " + raw_cat).lower() 
            for x in ["e-service", "télédéclaration", "télépaiement", "démarches", "en ligne", "espace", "enrôlement", "guichet numérique"]
        )
        
        service_entry = {
            "id": index,
            "name": name,
            "url": url,
            "description": desc,
            "history": history,
            "interest": interest,
            "categories": cats,
            "is_eservice": is_eservice
        }
        services.append(service_entry)
        index += 1
        
    out_dir = os.path.join("civ_helper", "data")
    os.makedirs(out_dir, exist_ok=True)
    out_file = os.path.join(out_dir, "directory.json")
    with open(out_file, "w", encoding="utf-8") as f:
        json.dump(services, f, ensure_ascii=False, indent=2)
    print(f"Generated {len(services)} public services in {out_file}")

if __name__ == "__main__":
    generate_directory_json()
